            )}
            {item.role === "held" && (
              <span className="text-[9px] px-1 rounded bg-[#3b82f6]/25 text-[#93c5fd]">held</span>
            )}
            {item.status !== "ok" && (
              <span className="text-[9px] px-1 rounded bg-amber-500/20 text-amber-300">{item.status}</span>
